challenges.description:
What does `value is Config` mean in the return type of this function?

  function isConfig(value: unknown): value is Config {
    return typeof value === 'object' && value !== null && 'host' in value
  }

What does `asserts value is string` do differently from a regular type guard?

  function assertString(value: unknown): asserts value is string {
    if (typeof value !== 'string') throw new Error('Expected string')
  }

  function process(val: unknown) {
    assertString(val)
    console.log(val.toUpperCase())  // ← what type is val here?
  }

What does TypeScript do when you declare the same interface twice?

  interface Config { host: string }
  interface Config { port: number }

  const c: Config = { host: 'localhost', port: 8080 }

Which narrowing technique is correct for each case?

  // Case 1: discriminated union
  type Event = { type: 'click'; x: number } | { type: 'key'; key: string }

  // Case 2: class hierarchy
  class AppError extends Error {}
  class NetworkError extends AppError { statusCode = 503 }

  function handle(e: AppError) { /* want to access statusCode */ }
